-- Telecom Customer Churn DB - MySQL import script
-- Generated for import into MySQL Workbench

CREATE DATABASE IF NOT EXISTS telecom_churn;
USE telecom_churn;

SET FOREIGN_KEY_CHECKS=0;

CREATE TABLE IF NOT EXISTS customers (
    customer_id VARCHAR(20) PRIMARY KEY,
    gender VARCHAR(10),
    senior_citizen TINYINT,
    partner VARCHAR(5),
    dependents VARCHAR(5),
    signup_date DATE
);

CREATE TABLE IF NOT EXISTS accounts (
    customer_id VARCHAR(20) PRIMARY KEY,
    tenure_months INT,
    contract_type VARCHAR(30),
    paperless_billing VARCHAR(5),
    payment_method VARCHAR(40),
    monthly_charges DECIMAL(8,2),
    total_charges DECIMAL(10,2),
    churn VARCHAR(5),
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);

CREATE TABLE IF NOT EXISTS services (
    customer_id VARCHAR(20) PRIMARY KEY,
    phone_service VARCHAR(20),
    multiple_lines VARCHAR(20),
    internet_service VARCHAR(20),
    online_security VARCHAR(20),
    online_backup VARCHAR(20),
    device_protection VARCHAR(20),
    tech_support VARCHAR(20),
    streaming_tv VARCHAR(20),
    streaming_movies VARCHAR(20),
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);

CREATE TABLE IF NOT EXISTS support_tickets (
    ticket_id INT AUTO_INCREMENT PRIMARY KEY,
    customer_id VARCHAR(20),
    ticket_date DATE,
    issue_type VARCHAR(50),
    resolution_time_hours DECIMAL(6,1),
    satisfaction_score INT,
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);

CREATE TABLE IF NOT EXISTS monthly_usage (
    usage_id INT AUTO_INCREMENT PRIMARY KEY,
    customer_id VARCHAR(20),
    usage_month VARCHAR(7),
    data_gb DECIMAL(6,1),
    call_minutes DECIMAL(7,1),
    sms_count INT,
    FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
);






SET FOREIGN_KEY_CHECKS=1;
